message.content:
{
"css": ".mentor-body {
  font-size: 14px;
  line-height: 22px;
  font-weight: 500;
  color: var(--muted);
}

.mentor-role {
  margin-bottom: 4px;
}

.mentor-description {
  margin-bottom: 14px;
}

.mentor-footer {
  display: flex;
  flex-direction: row;
  justify-content: space-between;
  align-items: center;
  gap: 8px;
  margin-top: 14px;
  flex-wrap: wrap;
}

.mentor-footer button {
  padding: 2px 6px;
  border-radius: 6px;
  font-size: 14px;
  font-weight: 500;
  line-height: 1.5;
  background-color: var(--surface);
  color: var(--ink);
  border: none;
  cursor: default;
}"
}
